require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/helpers.php';requerirRol(['analista']);$u=usuarioActual();$id=(int)($_GET['id']??0);
$q=$pdo->prepare("SELECT t.*,d.nombre AS departamento,TRIM(CONCAT(COALESCE(p.nombre,''),' ',COALESCE(p.apellido,''))) AS solicitante,TRIM(CONCAT(COALESCE(ap.nombre,''),' ',COALESCE(ap.apellido,''))) AS analista FROM tickets t JOIN departamentos d ON d.id_departamentos=t.departamento_id JOIN usuarios su ON su.id_usuarios=t.solicitante_id LEFT JOIN perfiles_usuarios p ON p.usuario_id=su.id_usuarios LEFT JOIN usuarios au ON au.id_usuarios=t.analista_id LEFT JOIN perfiles_usuarios ap ON ap.usuario_id=au.id_usuarios WHERE t.id_tickets=? LIMIT 1");$q->execute([$id]);$t=$q->fetch();if(!$t){header('Location: tickets.php');exit;}
$yaMio=(int)$t['analista_id']===(int)$u['id'];$disponible=$t['analista_id']===null && $t['estado']==='pendiente';
?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket #<?=str_pad((string)$id,6,'0',STR_PAD_LEFT)?></title><link rel="icon" href="../assets/img/logo.png"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH" crossorigin="anonymous"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet" integrity="sha384-tViUnnbYAV00FLIhhi3v/dWt3Jxw4gZQcNoSCxCIFNJVCx7/D55/wXsrNIRANwdD" crossorigin="anonymous"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="app-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><div class="main"><?php include __DIR__.'/../includes/topbar.php'; ?><div class="content"><div class="card-panel" style="max-width:850px"><div class="panel-head"><h2>Ticket #<?=str_pad((string)$id,6,'0',STR_PAD_LEFT)?></h2><span class="badge <?= $t['estado']==='pendiente'?'badge-pendiente':'badge-proceso' ?>"><?=h(ucfirst(str_replace('_',' ',$t['estado'])))?></span></div><div class="panel-body"><h3 class="fs-5"><?=h($t['titulo'])?></h3><p class="mt-3" style="white-space:pre-wrap"><?=h($t['descripcion'])?></p><hr><div class="row g-3"><div class="col-md-6"><strong>Departamento</strong><div><?=h($t['departamento'])?></div></div><div class="col-md-6"><strong>Solicitante</strong><div><?=h($t['solicitante']?:'—')?></div></div><div class="col-md-6"><strong>Analista</strong><div><?=h($t['analista']?:'Sin asignar')?></div></div><div class="col-md-6"><strong>Creado</strong><div><?=date('d/m/Y H:i',strtotime($t['fecha_creacion']))?></div></div></div><?php if($disponible): ?><form action="tomar_ticket.php" method="post" class="mt-4"><?= csrf_field() ?><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-brand"><i class="bi bi-hand-index-thumb me-1"></i> Atender este ticket</button></form><?php elseif($yaMio): ?><div class="alert alert-success mt-4 mb-0">Este ticket está asignado a ti.</div><?php elseif($t['analista_id']!==null): ?><div class="alert alert-warning mt-4 mb-0">Este ticket ya fue tomado por otro analista.</div><?php endif; ?><a href="tickets.php" class="btn btn-outline-secondary mt-3">Volver a tickets</a></div></div></div></div></div></body></html>